<template><div class="page">
 <div class="page-header"><div><div class="page-title">余额预警通知</div><div class="note">每日 09:10 根据近7天日账单平均金额计算余额可用天数，默认不足3天时发送 Webhook。</div></div><el-button type="primary" :loading="syncing" @click="syncNow">立即同步并分析</el-button></div>
 <div class="cards"><el-card v-for="c in cards" :key="c.label" shadow="never"><div class="value" :class="c.type">{{c.value}}</div><div class="label">{{c.label}}</div></el-card></div>
 <el-tabs v-model="tab">
  <el-tab-pane label="预警账户" name="results"><el-card shadow="never"><el-form inline><el-form-item label="分析日期"><el-date-picker v-model="query.date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="账户"><el-input v-model="query.keyword" clearable placeholder="名称或编号"/></el-form-item><el-form-item label="状态"><el-select v-model="query.status" clearable><el-option label="余额预警" value="WARNING"/><el-option label="正常" value="NORMAL"/><el-option label="无账单数据" value="NO_DATA"/><el-option label="无余额数据" value="NO_BALANCE"/><el-option label="近期无消费" value="ZERO_CONSUMPTION"/><el-option label="已忽略" value="IGNORED"/></el-select></el-form-item><el-button @click="search">查询</el-button></el-form>
   <el-table :data="rows" v-loading="loading" border><el-table-column type="index" label="排名" width="70"/><el-table-column prop="accountName" label="账户名称" min-width="210"/><el-table-column label="当前余额" width="120"><template #default="{row}">{{money(row.balance)}}</template></el-table-column><el-table-column label="近7日消费" width="125"><template #default="{row}">{{money(row.sevenDayAmount)}}</template></el-table-column><el-table-column label="日均消费" width="115"><template #default="{row}">{{money(row.dailyAverage)}}</template></el-table-column><el-table-column label="样本" width="75"><template #default="{row}">{{row.sampleDays}}天</template></el-table-column><el-table-column label="预计可用" width="110"><template #default="{row}"><b :class="row.analysisStatus==='WARNING'?'bad':''">{{days(row.availableDays)}}</b></template></el-table-column><el-table-column label="预警线" width="90"><template #default="{row}">{{row.warningDays}}天</template></el-table-column><el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="statusType(row.analysisStatus)">{{statusLabel(row.analysisStatus)}}</el-tag></template></el-table-column></el-table>
   <el-pagination class="pager" v-model:current-page="page.pageNum" v-model:page-size="page.pageSize" :total="total" :page-sizes="[20,50,100]" layout="total,sizes,prev,pager,next" @current-change="loadResults" @size-change="search"/>
  </el-card></el-tab-pane>
  <el-tab-pane label="预警设置" name="rules"><el-card shadow="never"><div class="toolbar"><el-input v-model="ruleKeyword" clearable placeholder="搜索账户" style="max-width:280px" @keyup.enter="loadRules"/><el-button @click="loadRules">查询</el-button><el-button type="primary" @click="editDefault">系统默认预警线</el-button></div><el-table :data="rules" border v-loading="ruleLoading"><el-table-column prop="accountName" label="账户名称" min-width="220"/><el-table-column label="监控" width="80"><template #default="{row}">{{row.enabled?'启用':'停用'}}</template></el-table-column><el-table-column label="预警天数" width="110"><template #default="{row}">{{row.warningDays==null?'默认':row.warningDays+'天'}}</template></el-table-column><el-table-column label="Webhook" width="100"><template #default="{row}">{{row.webhookEnabled?'推送':'不推送'}}</template></el-table-column><el-table-column prop="remark" label="备注" min-width="160"/><el-table-column label="操作" width="80"><template #default="{row}"><el-button link type="primary" @click="editRule(row)">设置</el-button></template></el-table-column></el-table></el-card></el-tab-pane>
  <el-tab-pane label="运行记录" name="runs"><el-card shadow="never"><el-table :data="runs" border><el-table-column prop="triggerType" label="触发" width="130"><template #default="{row}">{{row.triggerType==='SCHEDULED_0910'?'09:10 自动':'手动'}}</template></el-table-column><el-table-column prop="analysisDate" label="分析日期" width="120"/><el-table-column prop="status" label="状态" width="90"><template #default="{row}">{{row.status==='SUCCESS'?'成功':row.status==='RUNNING'?'执行中':'失败'}}</template></el-table-column><el-table-column prop="accountCount" label="账户" width="80"/><el-table-column prop="successCount" label="成功" width="80"/><el-table-column prop="failedCount" label="失败" width="80"/><el-table-column prop="warningCount" label="预警" width="80"/><el-table-column prop="startedAt" label="开始时间" width="180"/><el-table-column prop="errorMessage" label="结果" min-width="180"/></el-table></el-card></el-tab-pane>
 </el-tabs>
 <el-dialog v-model="ruleVisible" :title="ruleForm.accountNumber==='__DEFAULT__'?'系统默认预警线':'账户余额预警设置'" width="520px"><el-form label-width="125px"><el-form-item v-if="ruleForm.accountName" label="账户">{{ruleForm.accountName}}</el-form-item><el-form-item label="参与监控"><el-switch v-model="ruleForm.enabled"/></el-form-item><el-form-item label="预警天数"><el-input-number v-model="ruleForm.warningDays" :min="0.1" :max="365" :precision="1"/><span class="unit">天</span></el-form-item><el-form-item label="Webhook推送"><el-switch v-model="ruleForm.webhookEnabled"/></el-form-item><el-form-item label="临时忽略"><el-date-picker v-model="ruleForm.ignoreRange" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始" end-placeholder="结束"/></el-form-item><el-form-item label="备注"><el-input v-model="ruleForm.remark" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="ruleVisible=false">取消</el-button><el-button type="primary" @click="saveRule">保存</el-button></template></el-dialog>
</div></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref,watch}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{balanceWarningApi}from'@/api/balanceWarning';const today=()=>{const d=new Date(),offset=d.getTimezoneOffset()*60000;return new Date(d.getTime()-offset).toISOString().slice(0,10)};const tab=ref('results'),overview=ref<any>({}),rows=ref<any[]>([]),rules=ref<any[]>([]),runs=ref<any[]>([]),total=ref(0),loading=ref(false),ruleLoading=ref(false),syncing=ref(false),ruleKeyword=ref(''),ruleVisible=ref(false);const query=reactive({date:today(),keyword:'',status:''}),page=reactive({pageNum:1,pageSize:20}),ruleForm=reactive<any>({});const cards=computed(()=>[{label:'分析账户',value:Number(overview.value.totalCount||0)},{label:'余额预警',value:Number(overview.value.warningCount||0),type:'bad'},{label:'余额正常',value:Number(overview.value.normalCount||0),type:'ok'},{label:'无账单数据',value:Number(overview.value.noDataCount||0),type:'muted'},{label:'无余额数据',value:Number(overview.value.noBalanceCount||0),type:'muted'},{label:'近期无消费',value:Number(overview.value.zeroConsumptionCount||0),type:'muted'}]);const money=(v:any)=>v==null?'-':`${Number(v).toFixed(2)}元`;const days=(v:any)=>v==null?'-':`${Number(v).toFixed(2)}天`;const statusLabel=(v:string)=>({WARNING:'余额不足',NORMAL:'正常',NO_DATA:'无账单数据',NO_BALANCE:'无余额数据',ZERO_CONSUMPTION:'近期无消费',IGNORED:'已忽略'}as any)[v]||v;const statusType=(v:string)=>v==='WARNING'?'danger':v==='NORMAL'?'success':v==='IGNORED'?'info':'warning';async function loadResults(){loading.value=true;try{overview.value=await balanceWarningApi.overview(query.date);const r:any=await balanceWarningApi.results({...page,...query});rows.value=r.records||[];total.value=Number(r.total||0)}finally{loading.value=false}}function search(){page.pageNum=1;loadResults()}async function loadRules(){ruleLoading.value=true;try{rules.value=await balanceWarningApi.rules(ruleKeyword.value) as any}finally{ruleLoading.value=false}}async function loadRuns(){runs.value=await balanceWarningApi.runs() as any}async function syncNow(){await ElMessageBox.confirm('将获取最新账户余额、补充缺失账单并发送余额预警 Webhook，是否继续？','立即分析');syncing.value=true;try{await balanceWarningApi.sync();ElMessage.success('余额预警分析已完成');await Promise.all([loadResults(),loadRuns()])}finally{syncing.value=false}}function editRule(row:any){Object.assign(ruleForm,{...row,enabled:!!row.enabled,webhookEnabled:!!row.webhookEnabled,ignoreRange:row.ignoreStartDate&&row.ignoreEndDate?[row.ignoreStartDate,row.ignoreEndDate]:[]});ruleVisible.value=true}async function editDefault(){const r:any=await balanceWarningApi.defaultRule();editRule({...r,accountNumber:'__DEFAULT__',accountName:''})}async function saveRule(){const range=ruleForm.ignoreRange||[];await balanceWarningApi.saveRule(ruleForm.accountNumber,{...ruleForm,ignoreStartDate:range[0]||null,ignoreEndDate:range[1]||null});ElMessage.success('余额预警设置已保存');ruleVisible.value=false;await loadRules()}watch(tab,v=>{if(v==='rules')loadRules();if(v==='runs')loadRuns()});onMounted(()=>Promise.all([loadResults(),loadRuns()]));</script>
<style scoped>.note{color:#909399;font-size:13px;margin-top:6px}.cards{display:grid;grid-template-columns:repeat(6,1fr);gap:12px;margin:14px 0}.cards .value{font-size:26px;font-weight:700}.cards .label{color:#909399;margin-top:5px}.ok{color:#67c23a}.bad{color:#f56c6c}.muted{color:#909399}.pager{margin-top:12px;justify-content:flex-end}.toolbar{display:flex;gap:10px;margin-bottom:14px}.unit{margin-left:8px;color:#909399}@media(max-width:768px){.cards{grid-template-columns:repeat(2,1fr)}.page-header{align-items:flex-start;gap:8px}.el-form{display:flex;flex-direction:column}.el-form-item{margin-right:0}.toolbar{flex-wrap:wrap}}</style>
